             Body = <!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Editar Libro</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            background: #1a1a2e;
            color: #e0e0e0;
            display: flex;
            justify-content: center;
            margin: 60px 16px 0;
        }
        .caja {
            background: #16213e;
            padding: 40px;
            border-radius: 12px;
            border: 1px solid #4a90d9;
            width: 380px;
            max-width: 100%;
            box-sizing: border-box;
        }
        h1 {
            color: #f0c040;
            text-align: center;
            margin-bottom: 24px;
        }
        label {
            display: block;
            margin-bottom: 4px;
            color: #aaa;
            font-size: .9em;
        }
        input {
            width: 100%;
            padding: 10px;
            margin-bottom: 16px;
            background: #0f3460;
            border: 1px solid #4a90d9;
            border-radius: 6px;
            color: #fff;
            box-sizing: border-box;
        }
        .check {
            align-items: center;
            display: flex;
            gap: 8px;
            margin-bottom: 16px;
        }
        .check input {
            margin: 0;
            width: auto;
        }
        button {
            width: 100%;
            padding: 12px;
            background: #4a90d9;
            border: none;
            border-radius: 6px;
            color: white;
            font-size: 1em;
            cursor: pointer;
        }
        a {
            display: block;
            text-align: center;
            margin-top: 16px;
            color: #4a90d9;
        }
    </style>
</head>
<body>
    <div class="caja">
        <h1>Editar Libro</h1>
        <form action="/actualizar/1"
              method="post">
            <label for="titulo">Título</label>
            <input type="text" placeholder="Título" required id="titulo" name="titulo" value="Dune">

            <label for="autor">Autor</label>
            <input type="text" placeholder="Autor" required id="autor" name="autor" value="Frank Herbert">

            <label for="genero">Género</label>
            <input type="text" placeholder="Novela, Ciencia, Historia..." id="genero" name="genero" value="Ciencia ficci&oacute;n">

            <label for="anio">Año de publicación</label>
            <input type="number" placeholder="2001" min="1" max="2100" id="anio" name="anio" value="1965">

            <label class="check">
                <input type="checkbox" id="disponible1" name="disponible" value="true" checked="checked"><input type="hidden" name="_disponible" value="on"/>
                Disponible para préstamo
            </label>

            <button type="submit">Actualizar libro</button>
        </form>
        <a href="/libros">Ver todos los libros</a>
    </div>
</body>
</html>

